  "otr-182": {
    "A": "Faux. Une fracture Garden IV du sujet âgé est de mauvais pronostic (déplacement majeur, risque de nécrose).",
    "B": "Vrai. Chez le sujet âgé, une fracture déplacée du col relève d’une arthroplastie (prothèse intermédiaire ou totale) pour permettre un lever immédiat.",
    "C": "Faux. L’absence de traitement entraîne une pseudarthrose ou une perte de la fonction, jamais un cal vicieux toléré.",
    "D": "Faux. Les travées sont déviées en varus (horizontalisées) dans les fractures déplacées.",
    "E": "Faux. La nécrose céphalique est fréquente après Garden IV.",
    "_synthese": "Garden III-IV du vieillard : prothèse (hémi-arthroplastie ou PTH) en urgence relative ; ostéosynthèse réservée au sujet jeune."
  },
