  "otr-726": {
    "A": "Vrai. La marche parkinsonienne se fait à petits pas, traînants, le pied décollant à peine du sol.",
    "B": "Faux. Le steppage (pied tombant avec lever exagéré du genou) évoque une paralysie des releveurs du pied, non un syndrome parkinsonien.",
    "C": "Vrai. Le ballant des bras est diminué ou aboli du côté atteint : c’est un signe précoce de la maladie.",
    "D": "Faux. La cadence n’est pas régulière : elle s’accélère par moments (festination) et des blocages (freezing) peuvent survenir.",
    "E": "Vrai. Le démarrage est lent, hésitant (difficulté d’initiation de la marche).",
    "_synthese": "Marche parkinsonienne : petits pas, perte du ballant des bras, démarrage difficile, festination et freezing, aspect penché en avant."
  },
  "otr-727": {
    "A": "Vrai. Le quadriceps freine la flexion du genou lors de la prise d’appui (contraction excentrique) et amortit la charge.",
    "B": "Faux. Le tibial antérieur retient la chute de l’avant-pied après le contact du talon et relève le pied en phase oscillante ; il n’est pas propulseur.",
    "C": "Vrai. Le triceps sural propulse le corps vers l’avant en fin de phase d’appui (poussée du pied).",
    "D": "Vrai. Le moyen fessier stabilise latéralement le bassin en appui unipodal.",
    "E": "Faux. Les ischio-jambiers sont extenseurs de la hanche et fléchisseurs du genou, non extenseurs du genou.",
    "_synthese": "Muscles de la marche : quadriceps freinateur à la prise d’appui, triceps sural propulseur en fin d’appui, moyen fessier stabilisateur latéral, tibial antérieur releveur du pied."
  },
  "otr-728": {
    "A": "Vrai. La boiterie d’esquive s’observe quelle que soit la cause de la douleur du membre inférieur (fracture, arthrite, tendinite, infection).",
    "B": "Faux. Le déficit du moyen fessier définit la boiterie de Trendelenburg.",
    "C": "Vrai. L’enfant ou l’adulte évite d’appuyer sur le membre douloureux et écourte le temps d’appui.",
    "D": "Faux. Le temps d’appui unipodal du côté douloureux est diminué, non augmenté.",
    "E": "Faux. L’élévation du bassin avec abduction de hanche décrit une marche en fauchage, non la boiterie d’esquive.",
    "_synthese": "Boiterie d’esquive : douleur du membre inférieur, appui écourté du côté malade, rythme asymétrique."
  },
  "otr-729": {
    "A": "Faux. Le quadriceps ne stabilise pas le bassin.",
    "B": "Faux. Le tibial antérieur relève le pied.",
    "C": "Faux. Le déficit concerne le moyen fessier du côté de l’appui et non du côté controlatéral.",
    "D": "Vrai. Un moyen fessier insuffisant du côté de l’appui ne retient plus le bassin, qui bascule du côté opposé.",
    "E": "Faux. Le grand fessier est extenseur de la hanche.",
    "_synthese": "Trendelenburg : insuffisance du moyen fessier du côté de l’appui, chute du bassin du côté opposé, compensée par une inclinaison du tronc."
  },
  "otr-730": {
    "A": "Vrai. L’ilio-psoas et les ischio-jambiers raccourcissent le membre inférieur en phase oscillante en fléchissant la hanche et le genou.",
    "B": "Vrai. Le triceps sural propulse le corps en fin d’appui.",
    "C": "Faux. La boiterie de Trendelenburg est due au moyen fessier, non au quadriceps.",
    "D": "Vrai. Le steppage est un défaut de raccourcissement du membre en phase oscillante : le pied tombant accroche le sol.",
    "E": "Vrai. La démarche cérébelleuse (ébrieuse) élargit le polygone de sustentation pour compenser l’instabilité.",
    "_synthese": "Marche : phase d’appui et phase oscillante ; steppage = défaut de relevé du pied ; démarche cérébelleuse = polygone élargi."
  },
  "otr-731": {
    "A": "Faux. Le défaut d’extension du genou en appui correspond à un déficit du quadriceps.",
    "B": "Vrai. Le steppage résulte d’un défaut de dorsiflexion du pied en phase oscillante (déficit des releveurs, nerf fibulaire).",
    "C": "Faux. Le défaut d’extension de la hanche relève du grand fessier.",
    "D": "Faux. L’élévation du bassin avec abduction décrit le fauchage.",
    "E": "Faux. L’évitement de l’appui du côté douloureux est la boiterie d’esquive.",
    "_synthese": "Steppage : pied tombant, genou fléchi haut en phase oscillante ; paralysie du nerf fibulaire commun ou du releveur du pied."
  },
  "otr-733": {
    "A": "Faux. Un cycle de marche du membre droit commence au contact initial du pied droit et se termine au contact suivant du même pied.",
    "B": "Vrai. L’ilio-psoas fléchit la hanche et raccourcit le membre en phase oscillante.",
    "C": "Vrai. Le triceps sural est propulseur en fin d’appui.",
    "D": "Faux. La boiterie de Trendelenburg est unilatérale ou bilatérale selon l’atteinte, mais cette formulation n’est pas la définition.",
    "E": "Vrai. Le steppage est un défaut de raccourcissement du membre en phase oscillante.",
    "_synthese": "Cycle de marche : appui puis oscillant, de contact initial à contact initial du même pied."
  },
